                    query_params = {}

                    for param in params:
                        param_name = param.get("name")
                        param_in = param.get("in", "query")

                        if param_name not in kwargs:
                            continue

                        if param_in == "path":
                            url = url.replace(f"{{{param_name}}}", str(kwargs[param_name]))
                        elif param_in == "query":
                            query_params[param_name] = kwargs[param_name]

                    # Build request kwargs
                    request_kwargs = {}
                    if query_params:
                        request_kwargs["params"] = query_params
                    if has_body and "body" in kwargs:
                        request_kwargs["json"] = kwargs["body"]

                    # Make the API call
                    response = await client.request(http_method.upper(), url, **request_kwargs)

                    # Parse response
                    try:
                        response_data = response.json()
                    except (json.JSONDecodeError, ValueError):
                        response_data = response.text

                    return json.dumps({
                        "status_code": response.status_code,
                        "headers": dict(response.headers),
                        "data": response_data
                    })

                return call_api

            # Register the tool with the server
